<script setup>
import {onMounted,ref,computed} from 'vue'
import {useI18n} from 'vue-i18n'
import {Cloud,UserRound,RefreshCw} from 'lucide-vue-next'
import {useAppStore} from '../../stores/app.js'
import {useSyncStore} from '../../stores/sync.js'
import SyncConflictList from './SyncConflictList.vue'
import GuestImportDialog from './GuestImportDialog.vue'
const app=useAppStore(),sync=useSyncStore(),{t,locale}=useI18n(),previewOpen=ref(false)
const disabled=computed(()=>sync.busy||sync.authBusy)
onMounted(()=>sync.prepare())
async function preview(){await sync.previewGuest();previewOpen.value=true}
async function importGuest(){await sync.importGuest();if(!sync.error)previewOpen.value=false}
function disconnect(){sync.disconnect(false)}
function revoke(){if(confirm(t('syncRevokeConfirm')))sync.disconnect(true)}
function erase(){if(confirm(t('syncDeleteConfirm')))sync.deleteCloud()}
function uploadRestore(){if(confirm(t('syncRestoreConfirm')))sync.run({approveRestore:true})}
function recover(){if(confirm(t('syncRecoverConfirm')))sync.run({recover:true})}
function resolve(choice){sync.resolve(choice.key,choice.id).catch(()=>app.error='storageError')}
const lastSync=computed(()=>app.sync.lastSync?new Intl.DateTimeFormat(locale.value,{dateStyle:'medium',timeStyle:'short'}).format(new Date(app.sync.lastSync)):t('syncNever'))
</script>
<template><section class="panel account-panel" aria-labelledby="account-heading"><div class="section-heading"><h2 id="account-heading"><UserRound :size="23"/>{{t('syncAccount')}}</h2><span class="pill" role="status" data-testid="sync-status">{{t(sync.status)}}</span></div><p class="muted">{{t('syncIntro')}}</p><p v-if="!sync.configured" class="callout">{{t('syncNotConfigured')}}</p><template v-else><button v-if="!app.identity" class="button primary" :disabled="!sync.googleReady||disabled" @click="sync.signIn">{{t('syncSignIn')}}</button><div v-else><div class="account-person"><b>{{app.identity.name||app.identity.email}}</b><span>{{app.identity.email}}</span></div><div class="sync-actions"><button class="button soft" :disabled="!sync.googleReady||sync.authBusy" @click="sync.signIn">{{t('syncSwitch')}}</button><button class="button soft" :disabled="sync.authBusy" @click="sync.signOut">{{t('syncSignOut')}}</button><button class="button soft" :disabled="disabled" @click="preview">{{t('syncImport')}}</button></div><div class="sync-consent"><Cloud :size="24"/><div><h3>{{t('syncDriveTitle')}}</h3><p>{{t('syncConsent')}}</p><p class="small muted">{{t('syncPrivacy')}}</p></div></div><div class="sync-actions"><button class="button primary" :disabled="!sync.googleReady||disabled" @click="sync.connect">{{t(app.sync.enabled?'syncReconnect':'syncEnable')}}</button><button v-if="app.sync.enabled" class="button soft" :disabled="disabled||app.sync.reviewRequired" @click="sync.run()"><RefreshCw :size="16"/>{{t('syncNow')}}</button><button v-if="app.sync.enabled" class="button soft" :disabled="disabled" @click="disconnect">{{t('syncDisconnect')}}</button></div><p class="sync-summary">{{t('syncPendingCount',{count:app.sync.pending.length})}} · {{t('syncLast')}}: {{lastSync}}</p><p v-if="app.sync.reviewRequired" class="callout">{{t('syncRestoreReview')}}<button class="button soft" :disabled="disabled" @click="uploadRestore">{{t('syncApproveRestore')}}</button></p><p v-if="sync.status==='syncCloudMissing'" class="callout">{{t('syncCloudMissingHelp')}}<button class="button soft" :disabled="disabled" @click="recover">{{t('syncRecover')}}</button></p><SyncConflictList :issues="sync.issues" :disabled="disabled" @resolve="resolve"/><details class="sync-management"><summary>{{t('syncManage')}}</summary><p class="muted">{{t('syncDeleteHelp')}}</p><div class="sync-actions"><button class="button soft" :disabled="disabled" @click="revoke">{{t('syncRevoke')}}</button><button class="button danger" :disabled="disabled" @click="erase">{{t('syncDeleteCloud')}}</button></div></details></div><button v-if="!sync.googleReady" class="button soft" @click="sync.prepare">{{t('retry')}}</button></template><p v-if="sync.error" class="error" role="alert">{{t(sync.error)}}</p><GuestImportDialog v-if="previewOpen" :data="sync.guestPreview" :disabled="disabled" @cancel="previewOpen=false" @confirm="importGuest"/></section></template>
<style scoped>
.account-panel{margin-bottom:24px}.account-panel h2{display:flex;gap:10px;align-items:center}.account-panel .section-heading{flex-wrap:wrap}.account-person{display:flex;flex-direction:column;gap:5px;overflow-wrap:anywhere;margin:20px 0}.account-person span{font-size:14px;color:var(--color-text-muted)}.sync-actions{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.sync-consent{display:flex;gap:14px;background:var(--color-primary-soft);border-radius:10px;padding:18px;margin-top:22px}.sync-consent>svg{flex-shrink:0;color:var(--color-primary)}.sync-consent p{font-size:14px}.sync-summary{font-size:13px;color:var(--color-text-muted)}.sync-management{margin-top:24px;padding-top:15px;border-top:1px solid var(--color-divider)}.sync-management summary{cursor:pointer;min-height:44px;font-weight:600}.sync-management p{font-size:14px}
</style>
